    "report": "Curry traf 2025/26 4,4 Dreier pro Spiel und erzielte 26,6 Punkte bei 92,3 % FT. Das kann zwei offensive FBA-Punkte stark prägen. Die Zahl daneben ist ebenso wichtig: Er absolvierte 43 Spiele. Bei seinem Profil muss der Draft-Preis deshalb sowohl die herausragende Produktion pro Abend als auch das Risiko deutlich kleinerer Wochensummen berücksichtigen.",
