    "report": "Flagg lieferte bereits in seiner ersten NBA-Saison 21,0 Punkte, 6,7 Rebounds und 4,5 Assists. Dazu kamen 1,2 Steals und 0,9 Blocks. Für einen Draft-Pick ist diese Verteilung interessant: Er kann offensiv und defensiv helfen, ohne dass sein Nutzen nur an einem einzigen Spezialgebiet hängt.",
