    "risk": "77,5 % FT bei vielen Versuchen sind kein automatischer Quotenanker. Mit 1,2 Dreiern und 0,6 Blocks waren andere Spieler für ausgeprägte Spezialrollen nötig.",
    "fit": "Sinnvoll für einen Kader, der offensive Verantwortung verteilen möchte und bereits verlässliche Quellen für Dreier oder Ringverteidigung besitzt.",
    "draftPlan": "Die gemeinsame Aufstellung ist wichtiger als die Annahme, ein offensiver Center mache automatisch jeden Mitspieler produktiver. Prüfe FG% und FT% gemeinsam mit deinen bisherigen Picks. Ergänze anschließend vor allem Blocks, Steals und ausreichend Distanztreffer. Ohne Turnover-Abzug bleibt Bancheros zusätzlicher Spielaufbau interessant; viele Punkte allein sollten dich trotzdem nicht über noch offene Aufgaben im restlichen Team hinwegtäuschen.",
