    "report": "Zubacs Vorjahresprofil ist erfreulich gut zu lesen. In der Saison 2025/26 lieferte er 14,1 Punkte und 10,6 Rebounds pro Spiel bei 59,8 % aus dem Feld. Dazu kamen 0,8 Blocks. Wer ihn draftet, erhält damit vor allem Produktion nahe am Korb und an den Brettern. Für eine Mannschaft mit offensiv starken Guards kann genau diese sachliche Ergänzung wertvoll sein.",
