    "reason": "Ein Center mit Rebounds, Dreiern und etwas Spielaufbau: Vučević füllt Lücken, die ein reiner Ringbeschützer oft offenlässt.",
    "report": "Vučević bietet eine andere Center-Mischung als der klassische Blocks-Spezialist. 2025/26 erzielte er 15,1 Punkte, holte 8,4 Rebounds und verteilte 3,3 Assists pro Spiel. Dazu kamen 1,6 Dreier. Für den Draft heißt das: Der Frontcourt kann zusätzliche Distanztreffer und Vorlagen liefern, statt nur zwei FBA-Punkte am Korb zu besetzen. Gerade neben einem defensiv geprägten Big entsteht daraus eine schlüssige Arbeitsteilung.",
