    "report": "Green erzielte 2025/26 17,8 Punkte und 2,2 Dreier pro Partie bei 42,2 % FG. Das sind Beiträge, die ein Team im Außenangriff gebrauchen kann, doch die Feldquote gehört zum selben Paket. Wer nur die Punkte addiert, übersieht einen möglichen Preis dieser Produktion. Für die FBA ist daher besonders wichtig, was dein Kader neben ihm bereits gut kann.",
