    "report": "Kesslers Saisonbasis 2025/26 umfasst nur fünf Spiele. Darin stehen 14,4 Punkte, 10,8 Rebounds und 1,8 Blocks pro Partie. Das Profil sieht für eine Innenachse reizvoll aus, die Aussagekraft ist aber deutlich begrenzt: Einzelne starke Abende verändern einen Fünf-Spiele-Schnitt wesentlich stärker als eine lange Saison. Für den Draft zählt deshalb sowohl die Richtung seiner Beiträge als auch die geringe Belastbarkeit dieser Zahlen.",
    "outlook": "Bei den Lakers bietet Dončić Kessler einen starken Passpartner. Rebounds, Blocks und Abschlüsse am Ring passen dazu. Seine sehr kleine Vorjahresstichprobe bleibt dennoch ein Risiko; ein idealer Pick-and-Roll-Partner garantiert weder Gesundheit noch eine feste Minutenmenge.",
