    "reason": "Ein offensiver Flügel mit Dreiern und guten Freiwürfen – die Passung entsteht durch deinen Bedarf, nicht allein durch frühere Scoring-Reputation.",
    "report": "LaVine erzielte 2025/26 19,2 Punkte und 2,5 Dreier pro Partie, dazu traf er 88,0 % FT. Damit liefert er eine klare offensive Richtung für den Draft. Wenn dein Kader bereits Rebounds, Assists und defensive Produktion besitzt, können zusätzliche Punkte und Distanztreffer genau die richtige Ergänzung sein. Fehlen diese Grundlagen noch, löst ein weiterer Scorer dagegen nur einen Teil des Problems.",
    "outlook": "DeRozans gemeldeter Abgang könnte LaVine zusätzliche Würfe geben. Eine Simmons-Verpflichtung würde zugleich die Raumaufteilung verändern. Mehr Volumen kann die Feldquote belasten; deshalb nicht höhere Punkte und bessere Effizienz gleichzeitig als sicheren Zugewinn einplanen.",
    "strengths": "Punkte · Dreier · FT% · offensiver Abschluss",
    "risk": "39 Vorjahreseinsätze; mit 2,8 Rebounds und 2,3 Assists pro Spiel bleibt das Paket außerhalb des Scorings eher schmal.",
    "fit": "Offensiver Ergänzungspick für einen Kader mit vorhandenen Ballverteilern und defensiv starken Bigs.",
    "draftPlan": "Mehr Volumen kann die Feldquote belasten; deshalb nicht höhere Punkte und bessere Effizienz gleichzeitig als sicheren Zugewinn einplanen. Prüfe deine Assistquellen und Ballgewinne, bevor du LaVine mit einem weiteren ähnlichen Schützen kombinierst. Seine Freiwurfquote kann helfen, doch das tatsächliche Versuchsvolumen bestimmt den Einfluss auf dein Team. Plane ausreichend verlässliche Einsätze um ihn herum und gib dem nächsten Pick eine Aufgabe, die seine Außenoffensive sinnvoll ergänzt.",
