    "id": "5061575",
    "reason": "Viele Dreier mit Rebounds und brauchbarem Spielaufbau – ein Außenprofil, das schon in seiner ersten Saison ungewöhnlich viel Substanz gesammelt hat.",
    "report": "Knueppel lieferte 2025/26 18,5 Punkte, 3,4 Dreier und 5,3 Rebounds pro Partie über 81 Einsätze. Für die FBA steckt darin mehr als ein reiner Wurfspezialist: Die Distanzproduktion treibt das Scoring, während die Rebounds einen weiteren Bereich abdecken. Ein Guard- oder Flügelplatz kann so die Außenoffensive stärken, ohne bei der Arbeit am Brett vollständig von deinen Bigs abhängig zu bleiben.",
    "outlook": "Ohne Ball und Miles Bridges muss Charlotte Aktionen neu verteilen. Knueppels Shooting könnte stärker gebraucht werden, White und Schröder übernehmen aber ebenfalls Organisation. Interessant ist die tatsächliche Dreiermenge; eine automatische große Assistrolle wäre zu weit gegriffen. Millers Trainingsbelastung könnte Knueppels frühe Wurfmenge beeinflussen. Ohne bestätigte Einschränkung aber keine zusätzliche Offense allein aus einer alten Verletzungsmeldung einplanen.",
