    "draftPlan": "Seine Vorlagen nicht auf eine bereits fertige neue Starting Five stützen; die echte Rotation ist der nächste Prüfpunkt. Ergänze Garland mit Rebounds und Blocks, aber behalte auch die Ballgewinne im Blick. Seine 86,1 % FT können in eine gute Freiwurfstruktur passen; der tatsächliche Einfluss hängt vom Volumen ab. Verteile die Verantwortung für Assists auf mehrere Spieler, wenn dein restlicher Kader bereits erhöhte Einsatzunsicherheit mitbringt.",
