    "id": "4277956",
    "reason": "Dreier als klarer Hebel, Feldquote als klarer Preis – Poole braucht einen sehr passenden Kader, damit aus Wurfvolumen nützlicher Mehrwert wird.",
    "report": "Poole lieferte 2025/26 13,4 Punkte und 2,5 Dreier pro Spiel, traf aber nur 37,2 % aus dem Feld. Für die FBA müssen beide Seiten gemeinsam gelesen werden: Die Distanztreffer können helfen, während die Fehlwürfe deine Teamquote belasten. Wer nur eine spektakuläre einzelne Scoring-Nacht im Kopf hat, könnte deshalb an der eigentlichen Frage vorbeidraften: Welche FBA-Punkte gewinnt dein Team durch dieses konkrete Paket dazu?",
    "outlook": "Mathurin wäre zusätzliche Konkurrenz um Abschlüsse, während Dejounte Murray ebenfalls Aufbauaufgaben beansprucht. Poole kann weiterhin Punkte und Dreier liefern, aber ein exklusiver Offensivauftrag ist nicht belegt. Für einen frühen Pick müsste sein tatsächliches Volumen klarer werden.",
