    "reason": "Eine klare Aufgabe für deinen Frontcourt: Feldquote und Rebounds stabilisieren – die Freiwürfe brauchen einen Plan.",
    "report": "Pöltls Saison 2025/26 erzählt eine andere Geschichte als die eines spektakulären Shotblockers. In 46 Einsätzen lieferte er 10,7 Punkte, 7,0 Rebounds und 70,0 % aus dem Feld. Diese Effizienz ist sein auffälligstes Argument: Ein Kader voller wurfstarker, aber weniger treffsicherer Guards kann genau diese Entlastung gebrauchen. Die 0,7 Blocks pro Partie mahnen allerdings zur Genauigkeit. Ein Center im Aufgebot bedeutet hier noch lange nicht, dass die Blocks bereits erledigt sind.",
    "outlook": "Der mögliche Leonard-Wechsel betrifft Poeltl indirekt: andere Flügelabschlüsse, andere defensive Unterstützung. Bis zum Vollzug bleibt diese Änderung hypothetisch. Seine eigenen Minuten und die Rolle als Abroller sind die belastbareren Größen für Rebounds und Feldquote.",
