    "name": "Andrew Wiggins",
    "reason": "Dreier, Steals und Blocks in derselben Flügelkarte – Wiggins bietet mehr als seine Punktezahl vermuten lässt.",
    "report": "Bei Wiggins lohnt sich der Blick rechts neben die Punkte. 2025/26 standen in 68 Spielen 15,4 Punkte, 2,0 Dreier, 1,1 Steals und 1,0 Blocks pro Partie. Gerade die Verbindung aus Distanzwurf und beiden defensiven FBA-Punkte kann einen FBA-Kader abrunden. Du bekommst mehrere kleinere Beiträge auf einmal, statt einen weiteren Spieler zu wählen, dessen Wert fast vollständig von hohen Punktzahlen abhängt. Diese Breite macht ihn beim Vergleich ähnlich teurer Flügel interessant.",
    "outlook": "Giannis und Portis verändern Miamis Frontcourt. Andrew Wiggins könnte häufiger als ergänzender Schütze gebraucht werden, eigene Kreation wird nicht automatisch größer. Seine Defensivbeiträge bleiben interessant, während Würfe und Rebounds mit den neuen Bigs geteilt werden müssen. Klay ist zusätzliche Konkurrenz um Flügelwürfe. Wiggins’ defensive Aufgabe kann wichtig bleiben, ohne dass sein Scoringvolumen wächst.",
    "strengths": "Dreier · Steals und Blocks vom Flügel · ergänzendes Scoring · mehrere Wege zum Beitrag",
    "risk": "Die einzelnen Beiträge sind kein sicherer Wochensieg. Werden gerade Steals und Blocks kleiner, bleibt ein gewöhnlicheres Flügelprofil zurück; einen großen Assistbedarf löst er ebenfalls nicht allein.",
    "fit": "Gut neben dominanten Spielmachern, die Punkte und Assists bereits liefern, während auf den Forward-Plätzen noch defensive Unterstützung fehlt.",
    "draftPlan": "Seine Defensivbeiträge bleiben interessant, während Würfe und Rebounds mit den neuen Bigs geteilt werden müssen. Vergleiche Wiggins mit den verfügbaren Spezialisten: Brauchst du unbedingt viele Assists oder Rebounds, suche gezielter. Fehlen dagegen mehrere kleine Bausteine gleichzeitig, ist sein breiteres Profil ein nachvollziehbarer Grund für den Pick.",
