    "name": "Onyeka Okongwu",
    "reason": "Ein Center mit Dreiern und Vorlagen: Okongwu öffnet im Frontcourt mehrere Wege, statt nur Rebounds abzuliefern.",
    "report": "Okongwus Vorjahresprofil fällt aus dem Raster eines reinen Ringbeschützers. In 74 Spielen der Saison 2025/26 sammelte er 15,2 Punkte, 7,6 Rebounds, 3,1 Assists und 1,9 Dreier pro Partie. Der Distanzwurf ist dabei für die Kaderplanung besonders praktisch: Wer schon einen Center ohne Dreier besitzt, kann auf dem zweiten Big-Platz trotzdem offensiv beweglich bleiben. Die Vorlagen helfen zusätzlich, damit Spielaufbau nicht ausschließlich auf den Schultern der Guards liegt.",
