    "draftPlan": "Johnsons Spielaufbau und die tatsächlichen Center-Minuten bleiben für seine Abschlüsse und Rebounds zentral. Ergänze je nach frühem Draft entweder einen stärkeren Rebounder oder einen verlässlichen Passgeber. Achte darauf, dass Vielseitigkeit nicht zu einem Kader führt, der überall ordentlich ist, aber nirgends genügend Vorsprung entwickelt.",
