    "reason": "Blocks mit eigenem Scoring: Sarr kann deinem Frontcourt eine klare defensive Richtung geben, ohne vorne leerzulaufen.",
    "report": "Sarr brachte 2025/26 in 48 Einsätzen 16,3 Punkte, 7,4 Rebounds und 2,0 Blocks pro Spiel zusammen. Dazu kam ein Dreier pro Partie. Das ist ein reizvoller Gegensatz: Die Blocks bilden einen deutlichen Schwerpunkt, trotzdem bleibt sein offensiver Beitrag nicht auf ein paar Abschlüsse direkt am Ring beschränkt. Für einen Kader, der früh Guards gewählt hat, kann diese Kombination den Frontcourt nachträglich aufwerten, ohne sämtliche übrigen FBA-Punkte aus dem Blick zu verlieren.",
    "outlook": "Ayton kommt zusätzlich zu Davis. Sarr hat damit mehr Konkurrenz um Minuten in der Zone und könnte öfter nach außen rücken. Das macht seinen Distanzwurf interessant, aber eine unveränderte Block- und Reboundmenge bei größerem Spacing ist keineswegs gesichert.",
