    "name": "Kevin Porter Jr.",
    "reason": "Assists und Steals mit richtigem Gewicht – Porters Vorjahresprofil ist verlockend, sein Einsatzumfang bleibt die entscheidende Frage.",
    "report": "Porter lieferte 2025/26 in 38 Spielen 17,4 Punkte, 7,4 Assists und 2,2 Steals pro Partie. Hinzu kamen 5,2 Rebounds. Das ist für einen Guard eine breite Kombination, die mehrere Kaderlücken gleichzeitig treffen kann. Besonders die Vorlagen und Ballgewinne machen ihn im FBA-Format interessant. Da Turnover hier kein FBA-Punkt sind, wird sein Spielaufbau nicht durch einen zusätzlichen Ballverlust-Abzug abgeschwächt. Der Blick auf die Gesamtzahl der Einsätze gehört trotzdem unmittelbar neben diese starken Durchschnitte.",
    "outlook": "Herro und LeVert bringen weitere Ballhandler nach Milwaukee. Porter könnte eigene Aufbauzeit verlieren, auch wenn Giannis’ Abgang Aktionen freigibt. Für Assists zählt die tatsächliche Zuständigkeit neben Rollins; freie Teamwürfe werden nicht automatisch zu Porters Vorlagen.",
