    "id": "6442",
    "name": "Kyrie Irving",
    "reason": "Der besondere Comeback-Pick: Kyries offensive Möglichkeiten sind spannend, doch für 2025/26 gibt es keine NBA-Statistikbasis.",
    "report": "Kyrie Irving setzte 2025/26 während seiner Kreuzband-Reha vollständig aus. Sein letzter aktiver Saisonvergleich stammt aus 2024/25: 24,7 Punkte, 4,6 Assists und 91,6 % FT. Diese älteren Zahlen erklären den Reiz des Namens, sie werden hier aber nicht als Vorjahresleistung oder neue Projektion ausgegeben. Im eingefrorenen NBA-Datensatz 2025/26 fehlt folglich ein bewertbares Profil; daraus darf weder ein erfundener FBA-Value noch eine angebliche Nullleistung werden.",
    "outlook": "Die erwartete Rückkehr nach der langen Verletzungspause trifft auf Flagg und neue Forward-Optionen mit Aldama und Risacher. Irving könnte weniger allein organisieren müssen. Eine sofortige Vollbelastung bleibt trotzdem ungesichert; den Draftpreis an bestätigte Einsätze statt frühere Höchstwerte knüpfen. Klays Abgang kann zusätzliche Guard-Würfe öffnen, beantwortet aber Irvings eigene Freigabe- und Belastungsfrage nicht.",
    "strengths": "Historisch starkes Scoring und Freiwürfe · zusätzlicher Spielaufbau · mögliches Comeback-Potenzial",
    "risk": "Ein ganzes Jahr ohne NBA-Einsatz schafft Abstand zur letzten belastbaren Saisonleistung. Selbst gute Nachrichten würden noch keine bestimmte Zahl an Spielen oder vollständige Wiederholung früherer Werte garantieren.",
    "fit": "Option für einen schon stabilen Kader, der einen bewussten Entwicklungsspielraum verträgt und seine Guard-Produktion nicht vollständig an diesen Pick bindet.",
    "draftPlan": "Eine sofortige Vollbelastung bleibt trotzdem ungesichert; den Draftpreis an bestätigte Einsätze statt frühere Höchstwerte knüpfen. Plane eine direkt einsetzbare Guard-Alternative ein. Lege vor dem Draft fest, wie lange dein Kader geringere Minuten oder Pausen verkraften würde. Sein möglicher Mehrwert ist interessant; die benötigte Absicherung muss im Preis mitgedacht werden.",
