    "name": "CJ McCollum",
    "reason": "Punkte und Dreier als klare Dienstleistung – McCollum ergänzt deinen Angriff, ohne ein kompletter Spielmacher sein zu müssen.",
    "report": "McCollums 2025/26-Bilanz bietet einen ziemlich direkten Draftauftrag: 18,7 Punkte und 2,5 Dreier pro Partie, ergänzt durch 3,9 Assists und 3,3 Rebounds. Diese Werte entstanden in 76 Einsätzen. Wer bereits einen dominanten Passgeber besitzt, kann auf dem nächsten Guard-Platz also offensives Volumen ergänzen, ohne dort zwingend noch einmal den Spielaufbau des gesamten Teams einkaufen zu müssen. Die Vorlagen sind hilfreich, sein deutlichstes Profil liegt aber beim Scoring und Distanzwurf.",
    "outlook": "Dort und Aaron Wiggins ergänzen Atlantas Flügel. McCollums Shooting kann neben Johnson und Daniels wichtig bleiben, zusätzliche Ballkontakte sind daraus aber nicht abzuleiten. Beobachte, ob er Angriffseinheiten führt oder überwiegend vorbereitete Würfe erhält.",
    "strengths": "Punkte · Dreier · ergänzender Spielaufbau · zuletzt großer Saisonumfang",
    "risk": "Ein offensiv geprägter Guard repariert weder Rebounds noch Blocks. Zudem waren die 77,2 % FT im Vorjahr keine Freiwurfgarantie; der Name allein sagt nichts über die Wirkung auf deine Teamquoten aus.",
    "fit": "Passend neben einem dominanten Big und einem starken Assistgeber, wenn der übrige Kader mehr Distanzwurf und Scoring vertragen kann.",
    "draftPlan": "Beobachte, ob er Angriffseinheiten führt oder überwiegend vorbereitete Würfe erhält. Decke zuerst die dünneren defensiven FBA-Punkte ab. Stehen danach mehrere ähnliche Scorer zur Auswahl, vergleiche ihre Wurfversuche und ergänzenden FBA-Punkten. McCollum ist besonders sinnvoll, wenn du sein konkretes offensives Paket brauchst und keine universelle Lösung erwartest.",
