    "id": "4431671",
    "name": "Jaden McDaniels",
    "reason": "Ein Flügel für die Balance: brauchbares Scoring, gute Quoten und Hilfe bei Steals sowie Blocks in einem Paket.",
    "report": "McDaniels muss einen FBA-Punkt nicht im Alleingang dominieren, um einen Draft sinnvoll abzurunden. 2025/26 sammelte er in 73 Spielen 14,8 Punkte, 1,1 Steals und 1,0 Blocks bei 51,5 % aus dem Feld. Gerade die Verbindung von defensiven Zahlen und Wurfeffizienz ist interessant, wenn deine frühen Picks bereits viel Offensive liefern. Er kann an Stellen helfen, an denen ein weiterer reiner Scorer hauptsächlich etwas verstärken würde, das dein Team ohnehin schon besitzt.",
    "outlook": "Randle und Reid gehen, Kuminga kommt, Ball verändert den Aufbau. McDaniels könnte andere Forward-Aufgaben erhalten; ein Teil der freien Minuten bleibt umkämpft. Mehr offene Würfe sind denkbar, doch seine Defensivarbeit allein garantiert kein größeres offensives Volumen.",
    "strengths": "Steals · Blocks vom Flügel · FG% · im Vorjahr ebenfalls brauchbare Freiwürfe",
    "risk": "Die moderate offensive Produktion begrenzt die Wirkung in Punkten und Assists. Wer McDaniels als späte Antwort auf einen großen Spielaufbau-Rückstand plant, verlangt seinem Profil zu viel ab.",
    "fit": "Ergänzung für Kader mit starken Ballhandlern und genügend Dreiern, die auf den Forward-Plätzen defensive Unterstützung ohne große Quotenschäden suchen.",
    "draftPlan": "Mehr offene Würfe sind denkbar, doch seine Defensivarbeit allein garantiert kein größeres offensives Volumen. Schau vor dem Pick auf deine schwächsten FBA-Punkte. Fehlen Steals und einzelne Blocks gleichzeitig, ist McDaniels besonders interessant. Brauchst du dagegen vor allem Volumen beim Scoring, kann ein offensiver Spezialist besser passen, selbst wenn dessen Gesamtprofil weniger ausgewogen wirkt.",
