    "id": "4431767",
    "name": "Christian Braun",
    "reason": "Effiziente Ergänzung statt lauter Statistik: Braun passt dann, wenn deine Stars schon die großen Aufgaben übernehmen.",
    "report": "Brauns Saison 2025/26 liefert ein eher ruhiges, aber klar lesbares Profil. In 44 Spielen kam er auf 12,0 Punkte, 4,8 Rebounds und 2,7 Assists bei 51,9 % FG. Die Feldquote ist besonders nützlich, wenn du zuvor mehrere Guards mit hoher Wurfmenge ausgewählt hast. Zugleich bringen Rebounds und Vorlagen kleine Beiträge außerhalb des reinen Scorings. Er verlangt deshalb keine komplette Veränderung deiner Draftidee, sollte aber auch nicht als heimlicher Superstar kalkuliert werden.",
    "outlook": "Watson geht, DeRozans Zugang ist gemeldet. Für Braun könnten Flügelminuten frei werden, während Würfe zu DeRozan wandern. Diese gegenläufigen Effekte sind entscheidend: mehr Einsatzzeit wäre nicht gleich mehr Scoring pro Minute.",
    "strengths": "FG% · Rebounds vom Guard oder Flügel · ergänzende Assists · unkompliziertes Zusatzscoring",
    "risk": "Mit ungefähr einem Dreier pro Spiel sowie kleinen Steal- und Blockbeiträgen bleiben mehrere FBA-Punkte begrenzt. Die 44 Einsätze des Vorjahres sind ebenfalls kein verlässlicher Maßstab für die komplette nächste Saison.",
    "fit": "Passend zu einem bereits offensiv tragfähigen Kader, der seine Feldquote stabilisieren und nebenbei etwas Rebounding auf den kleineren Positionen ergänzen möchte.",
    "draftPlan": "Diese gegenläufigen Effekte sind entscheidend: mehr Einsatzzeit wäre nicht gleich mehr Scoring pro Minute. Wähle Braun mit einer konkreten Aufgabe. Wenn dein Team noch einen großen Rückstand bei Dreiern oder Steals hat, priorisiere dort einen Spezialisten. Sind diese Bereiche abgedeckt, kann seine ausgewogenere Ergänzung mehr Sinn ergeben als noch ein ineffizienter Volumenscorer.",
