    "id": "4396971",
    "name": "Naz Reid",
    "reason": "Dreier aus dem Frontcourt, ohne die Bretter ganz aufzugeben – Reid ist ein gezielter Gegenentwurf zum klassischen Center.",
    "report": "Reid verband 2025/26 in 77 Spielen 13,6 Punkte, 6,2 Rebounds und 2,1 Dreier pro Partie. Dazu kam ungefähr ein Block je Einsatz. Diese Mischung kann einen FBA-Kader beweglicher machen: Wer bereits einen Big ohne Distanzwurf besitzt, muss mit einem weiteren Frontcourt-Platz nicht automatisch noch mehr Boden in der Dreierkategorie verlieren. Die Rebounds verhindern zugleich, dass du für den Wurf den gesamten klassischen Nutzen eines großen Spielers aufgibst.",
    "outlook": "Charlotte bietet Reid ein anderes Umfeld als Minnesota. Er könnte im Frontcourt mehr Verantwortung erhalten, muss aber seine Rolle zwischen anderen Bigs erst bestätigen. White und Schröder ersetzen Balls Aufbau; gute Distanzwürfe entstehen deshalb nicht automatisch im gleichen Umfang. Millers Rückkehrbelastung kann Charlottes Abschlussverteilung zusätzlich beeinflussen. Reids eigene Big-Minuten werden dadurch dennoch nicht automatisch größer.",
    "strengths": "Dreier vom Big-Platz · Rebounds · ergänzende Blocks · mehrere verwendbare FBA-Punkte",
    "risk": "45,6 % FG und 73,2 % FT im Vorjahr sind kein Paket, das beide Quoten automatisch verbessert. Ein werfender Center kann deine FBA-Punkte breiter machen und gleichzeitig andere Schwächen vergrößern.",
    "fit": "Besonders passend neben effizienten Innenspielern und starken Spielmachern, wenn der Frontcourt zusätzliche Dreier braucht, ohne völlig auf Rebounds und Blocks zu verzichten.",
    "draftPlan": "White und Schröder ersetzen Balls Aufbau; gute Distanzwürfe entstehen deshalb nicht automatisch im gleichen Umfang. Rechne Reid als Ergänzung zu deinem vorhandenen Big-Profil ein. Suche danach gezielt den stärkeren Rebounder oder Quotenspieler, der noch fehlt. Mehrere ähnliche werfende Bigs hintereinander können schöne Einzelkarten ergeben, aber dieselbe Schwäche im Team vervielfachen.",
