    "risk": "71,7 % FT bei 4,9 Versuchen pro Spiel können die Mannschaftsquote spürbar beeinflussen. Kleine Steal- und Blockbeiträge begrenzen außerdem seine Fähigkeit, einen defensiven Rückstand allein aufzuholen.",
    "fit": "Offensiver Flügel für Teams, deren Steals und Blocks bereits solide stehen und die bei Freiwürfen entweder ausreichend Gegengewicht besitzen oder bewusst eine andere Ausrichtung wählen.",
    "draftPlan": "Bis dahin bleibt die aktuelle Teamzuordnung bestehen; mögliche Effizienzgewinne und verlorenes Volumen nur als Szenario bewerten. Beurteile die Freiwürfe immer zusammen mit dem Volumen deiner übrigen Spieler. Ergänze anschließend einen defensiven Flügel oder zusätzlichen Distanzwurf. Barrett ist dann am schlüssigsten, wenn sein Scoring echte Arbeit erledigt und nicht nur bereits vorhandene Stärken verdoppelt.",
