    "reason": "Blocks, Distanzwurf und gute Freiwürfe aus dem Big-Platz – Porziņģis bringt reizvolle Zutaten, aber keine garantierte Saisonmenge.",
    "report": "Porziņģis lieferte 2025/26 in 32 Spielen 16,7 Punkte, 1,7 Dreier und 1,2 Blocks pro Partie bei 84,2 % FT. Gerade die Kombination aus Ringbeschützen und brauchbaren Freiwürfen macht diesen Big interessant. Du kannst defensive Produktion ergänzen, ohne dafür automatisch den klassischen Freiwurf-Nachteil eines Centers einzukaufen. Das Profil bleibt allerdings nur die halbe Draftgeschichte: Die kleine Zahl an Einsätzen muss genauso sichtbar sein wie der Nutzen einer einzelnen gespielten Partie.",
    "outlook": "Porziņģis bleibt in Golden State, während Butler weiter rehabilitiert. Sein Shooting könnte gebraucht werden, aber zusätzlicher Bedarf bedeutet keine verlässlich höhere Einsatzmenge. Die tatsächliche Belastung und die Aufteilung mit Green sind wichtiger als eine pauschale Aufwertung durch Butlers Fehlen. Moodys offene Verfügbarkeit verändert zusätzlich die Außenrotation. Porziņģis’ eigene Belastbarkeit bleibt davon unabhängig.",
