    "id": "4066354",
    "name": "Payton Pritchard",
    "reason": "Dreier mit echtem Spielaufbau: Pritchard kann deinem Guard-Bereich mehr geben als eine reine Schützenrolle.",
    "report": "Pritchards 2025/26-Profil verbindet zwei Aufgaben, die man im Draft sonst gern auf mehrere Spieler verteilt. In 79 Einsätzen standen 17,0 Punkte, 2,7 Dreier und 5,2 Assists pro Partie. Die 89,0 % an der Linie ergänzen das offensive Paket, allerdings bei begrenztem Versuchsumfang. Seine Vorlagen sind der wichtige Unterschied zu einem reinen Distanzschützen: Du kannst eine Lücke bei den Dreiern schließen, ohne beim Spielaufbau vollständig auf zusätzliche Hilfe zu verzichten.",
    "outlook": "Browns Abgang und Georges Zugang verändern Bostons Hierarchie. Pritchard könnte zusätzliche Aufbauphasen erhalten, muss sie aber mit White und Tatum teilen. Für seinen Wert zuerst die Minuten mit eigenem Ballbesitz prüfen, nicht bloß die frei gewordenen Würfe zählen.",
    "strengths": "Dreier · Assists · Punkte · starke historische Freiwurfquote",
    "risk": "Wenige Blocks und ein begrenzter Stealbeitrag lassen die Defense als Aufgabe für andere Spieler übrig. Die gute Freiwurfquote bei nur 1,7 Versuchen kann außerdem keine größeren Quotenschäden im Alleingang ausgleichen.",
