    "draftPlan": "Für seinen Wert zuerst die Minuten mit eigenem Ballbesitz prüfen, nicht bloß die frei gewordenen Würfe zählen. Ergänze einen Guard oder Flügel mit Ballgewinnen und halte den Frontcourt stark genug für Rebounds und Blocks. Vergleiche Pritchard besonders mit reinen Schützen: Wenn du seine Assists tatsächlich brauchst, ist das breitere Profil der entscheidende Mehrwert für deinen Kader.",
