    "report": "Sheppard stand 2025/26 in allen 82 Spielen auf dem Feld und lieferte pro Partie 13,5 Punkte, 2,8 Dreier und 1,5 Steals. Hinzu kamen 3,4 Assists. Diese Verbindung ist für einen späten Guard-Pick interessant: Du kannst den Distanzwurf ausbauen und gleichzeitig einen defensiven Beitrag bekommen. Er ist damit mehr als ein Schütze, den man nur für die Dreierzahl betrachtet. Die Vorlagen ergänzen das Paket, ohne daraus automatisch die Lösung für den gesamten Spielaufbau zu machen.",
    "outlook": "Smart erhöht Houstons Guard-Konkurrenz. Sheppards Distanzwurf kann trotzdem eine eigenständige Aufgabe sichern, doch Minuten und Aufbauanteile sind nicht garantiert. Vor einem Entwicklungsaufschlag beobachten, ob er regelmäßig auch die engen Schlussphasen bestreitet.",
    "strengths": "Dreier · Steals · zusätzliche Assists · im Vorjahr vollständiger Saisonumfang",
    "risk": "43,0 % FG bei 11,5 Würfen pro Spiel können auf die Teamquote drücken. Wer bereits viele Distanzschützen mit ähnlicher Effizienz besitzt, sollte den gemeinsamen Effekt stärker gewichten als einen einzelnen schönen Dreierschnitt.",
    "fit": "Passend zu effizienten Bigs und bereits vorhandenem Spielaufbau, wenn auf den Guard-Plätzen vor allem Dreier und Ballgewinne fehlen.",
    "draftPlan": "Vor einem Entwicklungsaufschlag beobachten, ob er regelmäßig auch die engen Schlussphasen bestreitet. Ergänze sichere Abschlüsse im Frontcourt und vergleiche seinen Nutzen in Steals mit den übrigen Schützen. Wenn deine Feldquote ohnehin fragil ist, sollte der Pick Teil einer bewussten FBA-Punkteentscheidung sein, statt diese Schwäche unbemerkt weiter zu verschärfen.",
