    "id": "5037871",
    "name": "Dylan Harper",
    "reason": "Ein junger Guard mit effizientem Fundament – Harpers nächster Schritt wäre spannend, muss im Draftpreis aber noch Platz zum Entstehen haben.",
    "report": "Harpers erste NBA-Saison 2025/26 umfasst 69 Einsätze mit 11,8 Punkten, 3,9 Assists und 3,4 Rebounds pro Partie bei 50,5 % aus dem Feld. Diese Kombination zeigt einen anderen Einstieg als das Profil eines reinen Dreierspezialisten. Der Spielaufbau und die Effizienz sind das interessante Fundament; die Punktzahl allein erzählt nur einen Teil der Geschichte. In einem Kader, der bereits hohe Wurfmengen trägt, kann ein solcher Guard eine andere Art von Ergänzung darstellen.",
    "outlook": "Fox und Castle stehen ebenfalls für Aufbauarbeit, Harris ergänzt den Angriff. Harper braucht deshalb konkrete Minuten mit eigener Verantwortung. Ein Entwicklungsschritt ist plausibel, aber weder mehr Würfe noch mehr Assists folgen allein aus seinem zweiten NBA-Jahr.",
    "strengths": "Assists als Entwicklungsbasis · FG% · Rebounds vom Guard · Potenzial bei wachsender Verantwortung",
