    "fit": "Spannend für einen bereits produktiven Kader, der einen jungen Guard mit Spielaufbaupotenzial ergänzen kann und den Distanzwurf anderweitig gesichert hat.",
    "draftPlan": "Ein Entwicklungsschritt ist plausibel, aber weder mehr Würfe noch mehr Assists folgen allein aus seinem zweiten NBA-Jahr. Lege neben Harper einen direkt belastbaren Assistgeber und genügend Schützen. Beobachte vor allem seine tatsächlichen Aufgaben im Angriff. So bleibt die mögliche Entwicklung eine Chance für dein Team, während dessen grundlegende FBA-Punkte auch ohne einen sofortigen Sprung funktionieren.",
