    "name": "Brandon Miller",
    "reason": "Ein Flügel mit Dreiermenge und starken Freiwürfen – Miller gibt deinem Angriff Schub, braucht aber ein Gegengewicht bei FG%.",
    "report": "Miller produzierte 2025/26 in 65 Spielen 20,2 Punkte und 3,1 Dreier pro Partie. Seine 4,9 Rebounds ergänzten das offensive Profil; an der Linie traf er 89,2 %. Gerade der Distanzwurf ist für die Draftplanung ein klares Argument. Du bekommst ihn auf einem Flügelplatz und musst die Dreier damit nicht ausschließlich über kleine Guards beschaffen. Die Freiwürfe passen zusätzlich zu einem Kader, der diese Quote bewusst konkurrenzfähig halten möchte.",
    "outlook": "Ball und Miles Bridges verlassen Charlotte. Miller könnte mehr Flügelabschlüsse erhalten, teilt sie aber mit Knueppel und den Guards. Nach gesundheitlichen Problemen ist zusätzlicher Bedarf kein Beweis für Belastbarkeit; Wurfmenge und Trainingsfreigabe getrennt bewerten. Millers Reha-Update gegenüber Rod Boone nach der Schulteroperation ersetzt noch keine uneingeschränkte Spielfreigabe. Für eine Aufwertung braucht es belastbare Trainings- und Einsatzmeldungen.",
