    "fit": "Passend zu effizienten Bigs und gutem Spielaufbau, wenn dein Kader mehr Distanzwurf von den Forward-Plätzen braucht und seine Freiwurfstärke ausbauen möchte.",
    "draftPlan": "Nach gesundheitlichen Problemen ist zusätzlicher Bedarf kein Beweis für Belastbarkeit; Wurfmenge und Trainingsfreigabe getrennt bewerten. Prüfe neben der Dreierzahl immer den gesamten Wurfmix deiner Mannschaft. Ergänze sichere Abschlüsse sowie die nötigen Steals und Blocks. Miller kann eine offensive Lücke gut adressieren; die restlichen Picks müssen dafür sorgen, dass sein Volumen nicht unbeabsichtigt deine Feldquote zur Schwachstelle macht.",
