    "id": "4351851",
    "name": "Anfernee Simons",
    "reason": "Dreier als klarer Spezialauftrag – Simons kann eine Wurflücke schließen, seine übrigen FBA-Punkte brauchen starke Mitspieler.",
    "report": "Simons lieferte 2025/26 in 55 Spielen 14,3 Punkte, 2,7 Dreier und 2,4 Assists pro Partie. Seine Freiwurfquote lag bei 89,6 %. Der Distanzwurf ist das eindeutigste Argument dieses Profils: Man muss keinen großen Sprung bei Rebounds oder Steals erwarten, um zu erkennen, wofür er einem FBA-Team helfen könnte. Gleichzeitig schützt ein so klarer Auftrag vor falschen Erwartungen. Ein Guard auf dem Kaderzettel ist hier noch keine umfassende Absicherung für den Spielaufbau.",
    "outlook": "In Philadelphia steht Simons hinter beziehungsweise neben Maxey, Brown und LeBron. Sein Shooting hat eine Aufgabe, ein großer eigener Aufbauanteil ist schwerer begründbar. Den früheren Scoringumfang deshalb nicht einfach übertragen und zunächst die Rolle der zweiten Einheit prüfen.",
