    "fit": "Passend für Teams mit funktionierendem Spielaufbau und starken defensiven Bigs, wenn auf einem Guard-Platz vor allem zusätzliche Dreier gebraucht werden.",
    "draftPlan": "Den früheren Scoringumfang deshalb nicht einfach übertragen und zunächst die Rolle der zweiten Einheit prüfen. Vergleiche ihn gezielt mit anderen Schützen und beachte dabei deren ergänzenden FBA-Punkten. Braucht dein Kader eigentlich Assists oder Ballgewinne, nimm nicht aus Gewohnheit den nächsten Scorer. Simons gewinnt als Pick an Sinn, wenn seine Spezialität genau den offenen FBA-Punkt trifft.",
