    "name": "Andrew Nembhard",
    "reason": "Spielaufbau mit Substanz: Nembhards Vorlagen können einen Draft retten, der bislang zu viel Scoring und zu wenig Assists gesammelt hat.",
    "report": "Nembhards 2025/26-Profil trägt einen deutlich sichtbaren Schwerpunkt. In 57 Spielen kam er auf 7,7 Assists pro Partie, ergänzt durch 16,9 Punkte und 1,9 Dreier. Seine 82,5 % FT runden die Offensive ab. Die Vorlagen sind das interessante Gegenmittel zu einem Kader, der früh effiziente Bigs oder reine Flügelscorer gewählt hat. Im FBA-Format bleiben sie zudem ohne zusätzlichen Turnover-Abzug stehen, weil Ballverluste hier keinen eigenen FBA-Punkt bilden.",
    "outlook": "Haliburtons erwartete Rückkehr könnte Nembhards Aufbauanteile verringern. Oubre erhöht außerdem die Konkurrenz auf dem Flügel. Gute reale Ergänzung und unveränderte Fantasy-Assists sind verschiedene Fragen; entscheidend sind die eigenen Guard-Minuten ohne Haliburton. Furphys Verletzung kann Flügelminuten offenhalten, kompensiert aber nicht automatisch die mit Haliburtons Rückkehr möglicherweise sinkenden Assistanteile.",
