    "risk": "44,2 % FG sowie geringe Block- und Reboundbeiträge begrenzen die Vielseitigkeit. Außerdem stammen die Werte aus 57 Einsätzen; die Qualität einer Partie und die Anzahl verfügbarer Partien müssen getrennt betrachtet werden.",
    "fit": "Besonders interessant neben starken Reboundern und Abschlussspielern, wenn dem Team ein zusätzlicher ernstzunehmender Passgeber fehlt und die Defense bereits anderweitig aufgebaut ist.",
    "draftPlan": "Gute reale Ergänzung und unveränderte Fantasy-Assists sind verschiedene Fragen; entscheidend sind die eigenen Guard-Minuten ohne Haliburton. Priorisiere nach dem Pick Steals und effiziente Abschlüsse. Wenn Assists deine klare Schwäche sind, vergleiche Nembhard zuerst mit den anderen verfügbaren Spielmachern. Ein Flügel mit höherem Punkteschnitt kann optisch attraktiver wirken und trotzdem weniger zu deinem konkreten Kaderproblem beitragen.",
