    "name": "Ausar Thompson",
    "reason": "Ballgewinne als Statement: Ausar kann deine defensive Identität schärfen – Dreier und Freiwürfe müssen bewusst anderswo herkommen.",
    "report": "Thompson lieferte 2025/26 in 73 Spielen 2,0 Steals, 5,7 Rebounds und 0,9 Blocks pro Partie bei 52,5 % aus dem Feld. Der Reiz dieses Flügelprofils liegt also deutlich neben dem Scoring. Wer bereits viele Punkte und Dreier besitzt, kann mit einem solchen Pick an den Stellen nachlegen, an denen offensiv prominente Namen oft wenig liefern. Besonders die Verbindung aus Ballgewinnen und Rebounds schafft eine andere Art von Beitrag auf dem Forward-Platz.",
    "outlook": "Collins und Joe erweitern Detroits Abschlussoptionen. Ausars Defense und Bewegung ohne Ball können daneben gefragt sein, sein eigener Wurf bleibt aber eine Rollenfrage. Zusätzliche Team-Offense ist kein Beleg für einen Dreiersprung bei ihm.",
    "strengths": "Steals · Rebounds vom Flügel · zusätzliche Blocks · FG%",
    "risk": "57,1 % FT im Vorjahr und nahezu kein Dreierbeitrag sind klare Einschränkungen. Mehrere Spieler mit demselben Muster können dich früh auf eine engere FBA-Punktestrategie festlegen, auch wenn ihre defensiven Zahlen einzeln begeistern.",
    "fit": "Gut neben starken Schützen und verlässlichen Passgebern, besonders wenn dein Team Freiwürfe bewusst geringer priorisiert oder genügend starkes Freiwurfvolumen als Gegengewicht besitzt.",
